{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Naltrexone, the closest structural analogue sharing the morphinan skeleton, N-cyclopropylmethyl, phenol, ketone, and ether bridge, has oral bioavailability of about 5% in healthy volunteers due to extensive first-pass hepatic metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Butorphanol, a morphinan opioid with a phenol and basic amine, has oral bioavailability of about 5% in humans due to hepatic first-pass effect.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "MK-458, a small molecule with a phenol and basic amine, showed absolute oral bioavailability of approximately 5% in Parkinson's patients, indicating strong absorption or first-pass limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Rotigotine, a related aminotetralin with a phenol and tertiary amine, has low oral bioavailability in humans, limiting its oral use.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Codeine, a tertiary-amine morphinan without a permanent charge, has oral bioavailability of 42-71% in healthy volunteers, showing that high F is possible in this scaffold when the amine is not quaternized.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C52"],
      "claim": "Morphine, a tertiary-amine morphinan, has absolute oral bioavailability of 23.8% for immediate-release oral dosing, near the threshold but still at or above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, an opium alkaloid with a tertiary amine, has absolute oral bioavailability of 30% in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a quaternary ammonium morphinan, closely resembling methylnaltrexone. The closest structural analogue, naltrexone, has low oral bioavailability (about 5-20%) due to first-pass metabolism, and the permanent positive charge in the query further impairs membrane permeability and absorption. Other morphinan/opioid analogues with low F (butorphanol ~5%, MK-458 ~5%, rotigotine low) support a low prediction. High-F analogues such as codeine, morphine, and noscapine are tertiary amines without the quaternary charge and are less transferable. Therefore, the query is predicted to have F < 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query itself or a quaternary ammonium morphinan is present in the evidence set.",
    "High-F analogues (codeine, morphine, noscapine) are tertiary amines; their favorable absorption may not transfer to a permanently charged quaternary ammonium.",
    "The extent of first-pass metabolism and possible active efflux for the query is not directly quantified.",
    "Formulation effects could alter oral bioavailability, but no query-specific formulation data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

